class NotImplementedYet(Exception):
    pass


class NotSupportedRadioType(Exception):
    def __init__(self, radio_type):
        super(NotSupportedRadioType, self).__init__(
            "Radio type: {} is not supported.".format(radio_type)
        )


class TelnetConnectionError(Exception):
    def __init__(self, connection_error_msg):
        super(TelnetConnectionError, self).__init__(connection_error_msg)


class NotSupportedFunctionForRmod(Exception):
    def __init__(self):
        super(NotSupportedFunctionForRmod, self).__init__(
            "This Keyword does not support this type of radio."
        )


class ConnectionError(Exception):
    pass


class KeyVerificationError(Exception):
    def __init__(self):
        super(KeyVerificationError, self).__init__(
            "Host key verification failed. Please add (RSA) key to the list of known hosts."
        )


class RadioDidNotRespond(Exception):
    def __init__(self, cmd):
        super(RadioDidNotRespond, self).__init__(
            "Radio did't respond. Command: {} return empty string".format(cmd)
        )
